#!/usr/bin/env python3
"""brief TRN-7 R-trn7-9 -- the native transient engine's external references, generated by ngspice.

For every bench <name>.cnl in this folder:
  1. circuitRF's translation writes its deck:   circuitrf netlist <name>.cnl -o <name>.cir
  2. a control block is added before .end -- run, linearize, write <name>.raw -- so ngspice itself puts its solution on the
     bench's output grid (Start to Stop at Step) by its own interpolation: nothing of circuitRF's resampling is in the
     reference. (".options INTERP" would say the same, but ngspice 47 writes a damaged rawfile with it: its header is
     repeated inside the data and its point count is one short.)
  3. ngspice runs the deck in batch mode:       ngspice -b -n <name>.cir
  4. the rawfile is read HERE, by this file's own reader (not circuitRF's), its vectors named back through the name map the
     deck's header carries, and written as <name>.csv: time, then one column per saved net, every value to 10 significant digits.

The deck as run, the .csv and ngspice-version.txt are committed; the rawfile is not. Run from the repository root:

    python3 -I testdata/transient/ngspice/generate.py [path/to/CircuitRF.Cli.dll] [path/to/ngspice]

Defaults: src/Cli/bin/Debug/net10.0/CircuitRF.Cli.dll (build it first) and the first ngspice on PATH.
"""
import os
import re
import shutil
import struct
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))


def read_raw(path):
    """A SPICE rawfile's last plot: (variable names, list of columns). Binary or ASCII, real values only."""
    data = open(path, "rb").read()
    pos = 0
    names, columns = None, None
    while pos < len(data):
        header = {}
        variables = []
        while True:
            end = data.index(b"\n", pos)
            line = data[pos:end].decode("utf-8", "replace").rstrip("\r")
            pos = end + 1
            key, _, value = line.partition(":")
            key = key.strip().lower()
            if key == "variables":
                for _ in range(int(header["no. variables"])):
                    end = data.index(b"\n", pos)
                    parts = data[pos:end].decode().split()
                    pos = end + 1
                    variables.append(parts[1])
                continue
            if key in ("binary", "values"):
                kind = key
                break
            header[key] = value.strip()
        if "complex" in header.get("flags", "").lower():
            raise SystemExit(f"{path}: a complex plot; this script reads transient (real) plots only")
        nv, npts = len(variables), int(header["no. points"])
        cols = [[0.0] * npts for _ in range(nv)]
        if kind == "binary":
            for p in range(npts):
                row = struct.unpack_from("<%dd" % nv, data, pos)
                pos += 8 * nv
                for v in range(nv):
                    cols[v][p] = row[v]
        else:
            tokens = data[pos:].split()
            t = 0
            for p in range(npts):
                t += 1  # the point's index
                for v in range(nv):
                    cols[v][p] = float(tokens[t])
                    t += 1
            pos = len(data)
        names, columns = variables, cols
        while pos < len(data) and data[pos:pos + 1] in (b"\n", b"\r", b" "):
            pos += 1
    return names, columns


def main():
    cli = sys.argv[1] if len(sys.argv) > 1 else os.path.join("src", "Cli", "bin", "Debug", "net10.0", "CircuitRF.Cli.dll")
    ngspice = sys.argv[2] if len(sys.argv) > 2 else shutil.which("ngspice")
    if not ngspice:
        raise SystemExit("no ngspice on PATH; pass its path as the second argument")
    banner = subprocess.run([ngspice, "-v"], capture_output=True, text=True).stdout
    version = re.search(r"ngspice-(\S+)\s*:", banner).group(1)
    for name in sorted(f[:-4] for f in os.listdir(HERE) if f.endswith(".cnl")):
        cnl, cir = os.path.join(HERE, name + ".cnl"), os.path.join(HERE, name + ".cir")
        raw, csv = os.path.join(HERE, name + ".raw"), os.path.join(HERE, name + ".csv")
        subprocess.run(["dotnet", cli, "netlist", cnl, "-o", cir], check=True, capture_output=True)
        deck = open(cir, encoding="utf-8").read()
        if ".control" in deck:
            raise SystemExit(f"{name}: the deck has a control block of its own; this script adds one")
        deck = deck.replace("\n.end\n", f"\n.control\nrun\nlinearize\nwrite {name}.raw\n.endc\n.end\n")
        open(cir, "w", encoding="utf-8", newline="\n").write(deck)
        nets = dict(re.findall(r"^\*\s+net (\S+) = (\S+)$", deck, re.M))
        subprocess.run([ngspice, "-b", "-n", cir], check=True, capture_output=True, cwd=HERE)
        variables, cols = read_raw(raw)
        os.remove(raw)
        header = ["time"]
        keep = [0]
        for i, v in enumerate(variables[1:], start=1):
            m = re.fullmatch(r"v\((.+)\)", v, re.I)
            if not m:
                continue
            deck_name = next((d for d in nets if d.lower() == m.group(1).lower()), None)
            header.append(nets[deck_name] if deck_name else m.group(1))
            keep.append(i)
        with open(csv, "w", encoding="utf-8", newline="\n") as f:
            f.write(",".join(header) + "\n")
            for p in range(len(cols[0])):
                f.write(",".join("%.10g" % cols[i][p] for i in keep) + "\n")
        print(f"{name}: {len(cols[0])} points, {len(keep) - 1} nets")
    with open(os.path.join(HERE, "ngspice-version.txt"), "w", encoding="utf-8", newline="\n") as f:
        f.write(f"ngspice-{version}\n")


if __name__ == "__main__":
    main()
